<template><u-popup :show="show" mode="bottom" :safe-area-inset-bottom="true" border-radius="28rpx" @close="close"><view class="sheet"><view class="sheet-head"><view><text class="title">选择购卡客户</text><text class="sub">支持姓名、手机号和会员号检索</text></view><u-icon name="close" size="20" color="#94a3b8" @click="close"/></view><view class="search"><u-search v-model="keyword" placeholder="搜索客户" :showAction="false" bgColor="#f1f5f9" @search="load" @clear="load"/><text class="create-link" @click="createVisible=true">快速创建</text></view><scroll-view scroll-y class="member-list"><view v-if="loading" class="loading"><u-loading-icon/></view><view v-for="row in rows" :key="row.member_id" class="member" @click="choose(row)"><view class="avatar">{{ String(row.display_name||'客').slice(0,1) }}</view><view class="member-main"><strong>{{ row.display_name }}</strong><text>{{ row.mobile_masked }} · 已有 {{ row.card_count||0 }} 张卡</text></view><u-icon name="arrow-right" color="#cbd5e1"/></view><u-empty v-if="!loading&&!rows.length" text="没有找到客户" mode="search"/></scroll-view></view></u-popup><u-popup :show="createVisible" mode="center" round="18" @close="createVisible=false"><view class="create-box"><text class="title">快速创建客户</text><u-input v-model="create.name" border="surround" placeholder="客户姓名"/><u-input v-model="create.mobile" border="surround" type="number" maxlength="11" placeholder="11 位手机号"/><view class="actions"><u-button text="取消" @click="createVisible=false"/><u-button type="primary" text="创建并选中" :loading="creating" @click="submitCreate"/></view></view></u-popup></template>
<script setup lang="ts">import{ref,watch}from'vue';import{getCardMemberOptions,memberCardRequestId,quickCreateCardMember}from'../api';const props=defineProps<{show:boolean}>(),emit=defineEmits(['update:show','select']);const keyword=ref(''),rows=ref<any[]>([]),loading=ref(false),createVisible=ref(false),creating=ref(false),create=ref({name:'',mobile:''});const close=()=>emit('update:show',false);const load=async()=>{loading.value=true;try{rows.value=((await getCardMemberOptions({keyword:keyword.value,limit:40})) as any)?.data||[]}finally{loading.value=false}};const choose=(r:any)=>{emit('select',r);close()};const submitCreate=async()=>{if(!create.value.name.trim()||!/^1\d{10}$/.test(create.value.mobile))return uni.showToast({title:'请填写姓名和正确手机号',icon:'none'});creating.value=true;try{const d:any=(await quickCreateCardMember({...create.value,request_id:memberCardRequestId('member')}))?.data;choose({member_id:d.member_id,display_name:d.member_name,mobile_masked:d.mobile_masked,card_count:0});createVisible.value=false;create.value={name:'',mobile:''}}finally{creating.value=false}};watch(()=>props.show,v=>{if(v){keyword.value='';load()}})</script>
<style scoped>.sheet{height:min(900rpx,78vh);padding:30rpx 26rpx;background:#fff}.sheet-head,.search,.member,.actions{display:flex;align-items:center;justify-content:space-between;gap:18rpx}.title,.sub{display:block}.title{color:#0f172a;font-size:32rpx;font-weight:700}.sub{margin-top:5rpx;color:#94a3b8;font-size:22rpx}.search{margin:24rpx 0}.search .u-search{flex:1}.create-link{white-space:nowrap;color:#3b6ef5;font-size:25rpx}.member-list{height:calc(100% - 160rpx)}.member{padding:22rpx 4rpx;border-bottom:1rpx solid #eef2f7}.avatar{display:flex;width:68rpx;height:68rpx;border-radius:50%;background:#eff6ff;color:#3b6ef5;align-items:center;justify-content:center;font-weight:700}.member-main{display:flex;flex:1;flex-direction:column;gap:7rpx}.member-main strong{font-size:28rpx}.member-main text{color:#64748b;font-size:23rpx}.loading{padding:80rpx}.create-box{width:580rpx;padding:32rpx}.create-box :deep(.u-input){margin-top:22rpx}.actions{margin-top:26rpx}.actions>*{flex:1}</style>
